export function Section({
  highlighted = "{{highlighted}}",
  accent = "{{accent}}",
}) {
  const box = (key) => ({ padding: 12, marginBottom: 6, background: highlighted === key ? "#24143008" : "#fff", border: `2px solid ${highlighted === key ? accent : "transparent"}`, borderRadius: 8, textAlign: "center" });
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 12, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#241430" }}>
      <div style={box("nav")}>Nav</div>
      <div style={box("hero")}>Hero</div>
      <div style={box("content")}>Content</div>
      <div style={box("footer")}>Footer</div>
      <p style={{ margin: "8px 0 0", fontSize: 11, color: "#241430aa" }}>A page is made of distinct sections &mdash; {highlighted} outlined</p>
    </div>
  );
}
